import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const label = headlineItem?.text ?? 'Get started';
  const fontSize = headlineItem?.typography?.fontSize ?? 42;

  const group = new THREE.Group();
  group.name = 'cta-get-started';

  // inner container carries all visual weight + entrance/idle motion,
  // keeping the outer group's transform untouched (adapter owns scenePosition).
  const inner = new THREE.Group();
  group.add(inner);

  // ---------- button body (extruded, beveled-feel via multi-segment box) ----------
  const width = 2.2;
  const height = 0.62;
  const depth = 0.14;

  const bodyGeo = new THREE.BoxGeometry(width, height, depth, 4, 2, 1);
  const bodyMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });
  if (bodyMat.anisotropy !== undefined) bodyMat.anisotropy = 0.4;

  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.name = 'cta-body';
  inner.add(body);

  let bodyTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      bodyTexture = tex;
      bodyMat.map = tex;
      bodyMat.needsUpdate = true;
    });
  }

  // ---------- accent stripe (signal red, thin, <=10% of frame) ----------
  const stripeGeo = new THREE.BoxGeometry(width * 0.86, 0.045, depth * 1.05);
  const stripeMat = new THREE.MeshStandardMaterial
    ? null
    : null;
  const accentMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.3,
    roughness: 0.4,
    metalness: 0.2,
    clearcoat: 0.15,
  });
  const stripe = new THREE.Mesh(stripeGeo, accentMat);
  stripe.position.set(0, -height / 2 + 0.08, depth / 2 + 0.005);
  stripe.name = 'cta-accent-stripe';
  inner.add(stripe);

  // ---------- label text ----------
  const text = ctx.fontAtlas.createText(label, {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  text.position.set(0, 0.05, depth / 2 + 0.02);
  text.name = 'cta-label-text';
  inner.add(text);

  // ---------- contact shadow (radial falloff via TSL) ----------
  const shadowGeo = new THREE.PlaneGeometry(width * 1.35, height * 2.1, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const suv = uv();
  const centeredUv = suv.sub(vec2(0.5, 0.5));
  const dist = centeredUv.length();
  const falloff = smoothstep(0.5, 0.0, dist).mul(0.5);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = falloff;
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -height / 2 - 0.02, depth / 2 - 0.4);
  shadow.name = 'cta-contact-shadow';
  inner.add(shadow);

  // ---------- node-local rim light (accent hue, intensity within cap) ----------
  const rim = new THREE.PointLight(new THREE.Color(colors.accent), 0.9, 4.5, 2.0);
  rim.position.set(-1.4, 0.6, 1.2);
  rim.name = 'cta-rim-light';
  inner.add(rim);

  // ---------- motion ----------
  // entrance: weighted-settle, translate <=0.4 units, overshoot 1.04 -> 1.0, power4.out
  inner.position.y = -0.35;
  inner.scale.setScalar(0.96);

  const entranceTl = gsap.timeline();
  entranceTl.to(inner.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  entranceTl.to(
    inner.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.35,
      ease: 'power2.out',
    },
    0
  );
  entranceTl.to(inner.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });

  // idle: single slow breathing transform (<=2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.1 });
  idleTl.to(inner.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    entranceTl.kill();
    idleTl.kill();
    gsap.killTweensOf(inner.position);
    gsap.killTweensOf(inner.scale);

    bodyGeo.dispose();
    bodyMat.dispose();
    stripeGeo.dispose();
    accentMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (bodyTexture) bodyTexture.dispose();

    if (text.userData?.cleanup) text.userData.cleanup();
    if (text.geometry) text.geometry.dispose();
    if (text.material) text.material.dispose();

    inner.remove(rim);
    inner.clear();
    group.clear();
  };

  return group;
}
